1	<meta charset="utf-8">
2	<title>Zero Trust Identity Map</title>
3	<meta name="claude:viewport-fit-sides" content="cover">
4	<style>
5	/* Layout: the Maester report shell. One pillar: summary, where you are, a picker of functional areas, then the area's board (swimlanes as rows, workshop phases as columns) with the task panel beside it. */
6	:root{--bg:#fafafa;--panel:#ffffff;--fg:#0a0a0a;--muted:#6b6b6b;--faint:#a3a3a3;--line:#e5e5e5;--line2:#d4d4d4;--soft:#f4f4f5;
7	--brand:#e5484d;--done:#3f8f2f;--done-bg:#ecf6e8;--part:#b7791f;--part-bg:#fbf3e2;--fail:#d4383b;--fail-bg:#fdecec;--na:#8a8a8a;--na-bg:#f1f1f1;--accent:#2563eb;--accent-bg:#eef3ff;
8	--sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}
9	@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0b0b0b;--panel:#141414;--fg:#f5f5f5;--muted:#a1a1a1;--faint:#6b6b6b;--line:#262626;--line2:#333;--soft:#1c1c1c;--done:#7cc463;--done-bg:#16240f;--part:#e0a64a;--part-bg:#2a1f0c;--fail:#f07174;--fail-bg:#2c1213;--na:#8f8f8f;--na-bg:#1f1f1f;--accent:#7aa2ff;--accent-bg:#14203b;color-scheme:dark}}
10	:root[data-theme="dark"]{--bg:#0b0b0b;--panel:#141414;--fg:#f5f5f5;--muted:#a1a1a1;--faint:#6b6b6b;--line:#262626;--line2:#333;--soft:#1c1c1c;--done:#7cc463;--done-bg:#16240f;--part:#e0a64a;--part-bg:#2a1f0c;--fail:#f07174;--fail-bg:#2c1213;--na:#8f8f8f;--na-bg:#1f1f1f;--accent:#7aa2ff;--accent-bg:#14203b;color-scheme:dark}
11	*{box-sizing:border-box}
12	body{background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:14px;line-height:1.5}
13	.shell{display:grid;grid-template-columns:210px minmax(0,1fr);min-height:100vh}
14	aside{border-right:1px solid var(--line);padding:16px 12px;background:var(--panel)}
15	.brand{display:flex;align-items:center;gap:8px;font-weight:600;margin:0 4px 18px}
16	.brand i{width:10px;height:14px;background:var(--brand);border-radius:6px 6px 3px 3px;display:inline-block}
17	.navh{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--faint);margin:14px 6px 6px}
18	.nav a{display:flex;justify-content:space-between;padding:6px 8px;border-radius:6px;color:var(--fg);text-decoration:none;font-size:13px}
19	.nav a.on{background:var(--soft);font-weight:600}
20	.nav a.off{color:var(--muted)}
21	.nav a small{color:var(--faint);font-variant-numeric:tabular-nums}
22	main{padding-block:20px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));max-width:1480px;width:100%;min-width:0}
23	.eyebrow{font-size:12px;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
24	h1{font-size:26px;margin:2px 0 4px;text-wrap:balance}
25	h2{font-size:16px;margin:0 0 4px}
26	.lede{color:var(--muted);max-width:75ch;margin:0 0 14px}
27	.sample{display:inline-block;font-size:12px;background:var(--part-bg);color:var(--part);padding:2px 8px;border-radius:999px;margin-left:6px;vertical-align:middle;font-weight:500}
28	.tiles{display:flex;flex-wrap:wrap;gap:8px 18px;margin:0 0 16px;font-size:13px;color:var(--muted)}
29	.tiles b{color:var(--fg);font-size:15px;font-variant-numeric:tabular-nums;margin-right:2px}
30	.tiles span{display:flex;align-items:center;gap:6px}
31	.dot{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}
32	.d-done{background:var(--done)}.d-partial{background:var(--part)}.d-notdone{background:var(--fail)}.d-manual{background:transparent;border:1.5px dashed var(--na)}.d-unknown{background:var(--na)}
33	.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin-bottom:16px}
34	.where{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:20px}
35	.phases{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}
36	.phase{border:1px solid var(--line);border-radius:8px;padding:8px 10px}
37	.phase.cur{border-color:var(--accent);background:var(--accent-bg)}
38	.phase .n{font-size:12px;color:var(--muted)}
39	.bar{height:6px;border-radius:3px;background:var(--soft);display:flex;overflow:hidden;margin-top:6px}
40	.bar span{display:block;height:100%}
41	.sec{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin:0 0 6px}
42	ol.next{margin:0;padding:0;list-style:none;display:grid;gap:2px}
43	ol.next li button{all:unset;box-sizing:border-box;display:grid;grid-template-columns:20px minmax(0,1fr) auto;gap:8px;width:100%;padding:7px 8px;border-radius:8px;cursor:pointer}
44	ol.next li button:hover{background:var(--soft)}
45	ol.next .num{color:var(--faint);font-variant-numeric:tabular-nums}
46	ol.next .why,.why{font-size:12px;color:var(--muted)}
47	.pill{font-size:11px;padding:1px 7px;border-radius:999px;border:1px solid var(--line2);color:var(--muted);white-space:nowrap}
48	.pill.fail{background:var(--fail-bg);color:var(--fail);border-color:transparent}.pill.pass{background:var(--done-bg);color:var(--done);border-color:transparent}.pill.skip{background:var(--na-bg);color:var(--na);border-color:transparent}
49	.pill.mae{background:var(--accent-bg);color:var(--accent);border-color:transparent}
50	.areas{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-bottom:12px}
51	.area{all:unset;box-sizing:border-box;cursor:pointer;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;display:grid;gap:2px}
52	.area:hover{border-color:var(--line2)}
53	.area[aria-pressed="true"]{border:2px solid var(--accent);padding:9px 11px}
54	.area .t{font-weight:600;font-size:13px;line-height:1.3}
55	.area .why{margin-top:2px}
56	.work{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:16px;align-items:start}
57	.boardhead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:10px}
58	.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted)}
59	.legend span{display:flex;align-items:center;gap:5px}
60	label.tog{font-size:12px;color:var(--muted);display:flex;gap:6px;align-items:center;cursor:pointer}
61	.board{display:grid;grid-template-columns:minmax(120px,170px) repeat(3,minmax(0,1fr));border-top:1px solid var(--line)}
62	.board .ph{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;padding:8px 8px;border-bottom:1px solid var(--line)}
63	.board .ph b{color:var(--fg);letter-spacing:0;text-transform:none;font-size:13px;margin-right:4px}
64	.lane{padding:12px 10px 12px 0;border-bottom:1px solid var(--line)}
65	.lane .t{font-weight:600;font-size:13px;line-height:1.3}
66	.cell{padding:10px 8px;border-bottom:1px solid var(--line);border-left:1px dashed var(--line);display:flex;flex-direction:column;gap:6px;min-width:0}
67	.cell .phl{display:none;font-size:11px;color:var(--faint);text-transform:uppercase;letter-spacing:.05em}
68	.task{all:unset;box-sizing:border-box;cursor:pointer;display:grid;grid-template-columns:12px minmax(0,1fr);gap:4px 7px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel);font-size:13px;line-height:1.35}
69	.task:hover{border-color:var(--line2);background:var(--soft)}
70	.task .dot{margin-top:4px}
71	.task .sub{grid-column:2;font-size:11.5px;color:var(--muted)}
72	.task.sel{border:2px solid var(--accent);padding:6px 8px}
73	.task.manual{background:transparent;border-style:dashed}
74	.task.manual .nm{color:var(--muted)}
75	.task:focus-visible,.area:focus-visible,ol.next li button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
76	.detail{position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto}
77	.detail h3{font-size:17px;margin:4px 0 6px;text-wrap:balance}
78	.meta{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 12px}
79	.status{display:flex;align-items:center;gap:8px;font-weight:600;margin-bottom:8px}
80	.checks{display:grid;gap:6px;margin:0 0 12px}
81	.chk{display:grid;grid-template-columns:auto minmax(0,1fr);gap:8px;align-items:start;font-size:13px}
82	.chk .id{font-family:var(--mono);font-size:12px;color:var(--muted)}
83	.chk .src{font-size:11px;color:var(--faint)}
84	.detail .sec{margin-top:14px}
85	.doc{font-size:13px}
86	.doc h1,.doc h2{font-size:14px;margin:12px 0 4px}
87	.doc a,.detail a{color:var(--accent)}
88	.note{background:var(--accent-bg);border-radius:8px;padding:8px 10px;font-size:13px;margin-bottom:10px}
89	.empty{color:var(--muted);font-size:13px}
90	@media (max-width:1180px){.work{grid-template-columns:minmax(0,1fr)}.detail{position:static;max-height:none}}
91	@media (max-width:900px){.where{grid-template-columns:minmax(0,1fr)}}
92	@media (max-width:760px){.shell{grid-template-columns:minmax(0,1fr)}aside{display:none}
93	 .board{grid-template-columns:minmax(0,1fr);border-top:0}.board .ph{display:none}
94	 .lane{border-bottom:0;padding:14px 0 4px}.cell{border-left:0;border-bottom:0;padding:4px 0}.cell .phl{display:block}.cell.none{display:none}}
95	</style>
96	<div class="shell">
97	<aside>
98	<div class="brand"><i></i>Maester <span style="font-weight:400;color:var(--muted)">Report</span></div>
99	<div class="navh">Summary</div>
100	<nav class="nav"><a class="off" href="#">Overview</a><a class="off" href="#">Action plan</a><a class="off" href="#">All tests</a></nav>
101	<div class="navh">Zero Trust</div>
102	<nav class="nav" id="pillarnav"></nav>
103	</aside>
104	<main>
105	<div class="eyebrow">Zero Trust · Microsoft Zero Trust Workshop</div>
106	<h1>Identity <span class="sample">Sample results</span></h1>
107	<p class="lede">The workshop's Identity plan, area by area. Each area's tasks run left to right through the workshop's phases, coloured by what this run found. Tasks Maester can't check stay on the board so you see the whole plan.</p>
108	<div class="tiles" id="tiles"></div>
109	<section class="card where" id="where"></section>
110	<div class="sec">Functional areas</div>
111	<div class="areas" id="areas" role="group" aria-label="Functional areas"></div>
112	<div class="work">
113	<section class="card" style="margin:0;min-width:0">
114	<div class="boardhead"><h2 id="areatitle"></h2>
115	<div style="display:flex;gap:14px;flex-wrap:wrap;align-items:center"><label class="tog"><input type="checkbox" id="hidedone"> Hide done</label><label class="tog"><input type="checkbox" id="onlychecked"> Only what Maester checks</label></div></div>
116	<div class="legend" style="margin-bottom:10px"><span><i class="dot d-done"></i>Done</span><span><i class="dot d-partial"></i>Partly done</span><span><i class="dot d-notdone"></i>Not done</span><span><i class="dot d-unknown"></i>Couldn't check</span><span><i class="dot d-manual"></i>Review yourself</span></div>
117	<div class="board" id="board"></div>
118	</section>
119	<section class="card detail" id="detail" style="margin:0" aria-live="polite"></section>
120	</div>
121	</main>
122	</div>
123	<script src="https://cdnjs.cloudflare.com/ajax/libs/marked/12.0.2/marked.min.js"></script>
124	<script src="https://cdnjs.cloudflare.com/ajax/libs/dompurify/3.1.6/purify.min.js"></script>
125	<script id="data" type="application/json">__DATA__</script>
126	<script>
127	const D=JSON.parse(document.getElementById('data').textContent);
128	const byId=Object.fromEntries(D.tasks.map(t=>[t.id,t]));
129	const PHASES=['First','Then','Next'];const PH={First:0,Then:1,Next:2};const PR=p=>p?+p.slice(1):9;
130	const LABEL={done:'Done',partial:'Partly done',notdone:'Not done',manual:'Review yourself',unknown:"Couldn't check"};
131	const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
132	function status(t){const c=t.checks;if(!c.length)return 'manual';const r=c.filter(x=>x.result!=='Skipped');if(!r.length)return 'unknown';const f=r.filter(x=>x.result==='Failed').length;if(!f)return 'done';return f===r.length?'notdone':'partial'}
133	D.tasks.forEach(t=>{t.st=status(t);t.fails=t.checks.filter(c=>c.result==='Failed');t.passes=t.checks.filter(c=>c.result==='Passed')});
134	const checkable=D.tasks.filter(t=>t.st!=='manual');
135	const count=s=>D.tasks.filter(t=>t.st===s).length;
136	const blockers=t=>(t.dependencies||[]).map(d=>byId[d]).filter(d=>d&&d.st!=='done');
137	const pct=(n,d)=>d?n/d*100:0;
138	const bar=ts=>{const n=ts.length;return `<div class="bar"><span style="width:${pct(ts.filter(t=>t.st==='done').length,n)}%;background:var(--done)"></span><span style="width:${pct(ts.filter(t=>t.st==='partial').length,n)}%;background:var(--part)"></span><span style="width:${pct(ts.filter(t=>t.st==='notdone').length,n)}%;background:var(--fail)"></span></div>`};
139	document.getElementById('pillarnav').innerHTML=`<a class="on" href="#">Identity <small>${D.tasks.length}</small></a>`+D.otherPillars.map(p=>`<a class="off" href="#" title="Same view in the full build">${p.name} <small>${p.tasks}</small></a>`).join('');
140	document.getElementById('tiles').innerHTML=['done','partial','notdone','unknown','manual'].map(s=>`<span><i class="dot d-${s}"></i><b>${count(s)}</b>${LABEL[s].toLowerCase()}</span>`).join('');
141	const phases=PHASES.map(p=>{const ts=checkable.filter(t=>t.phase===p);return{p,ts,done:ts.filter(t=>t.st==='done').length,manual:D.tasks.filter(t=>t.phase===p&&t.st==='manual').length}});
142	const cur=phases.find(x=>x.done<x.ts.length)||phases[2];
143	const next=checkable.filter(t=>t.st==='notdone'||t.st==='partial').sort((a,b)=>(PH[a.phase]-PH[b.phase])||(blockers(a).length-blockers(b).length)||(PR(a.priority)-PR(b.priority))||(b.fails.length-a.fails.length)).slice(0,5);
144	const areaName=id=>D.areas.find(a=>a.id===id)?.name;
145	document.getElementById('where').innerHTML=`<div><h2>Where you are</h2><p class="lede" style="margin:0">You're in the <b>${cur.p}</b> phase: ${cur.done} of the ${cur.ts.length} ${cur.p} tasks that Maester checks are done. The workshop finishes the First tasks before it starts the Then tasks.</p>
146	<div class="phases">${phases.map(x=>`<div class="phase ${x===cur?'cur':''}"><div class="n">${x.p}${x===cur?' · you are here':''}</div><b style="font-variant-numeric:tabular-nums">${x.done} of ${x.ts.length}</b>${bar(x.ts)}<div class="n" style="margin-top:4px">+${x.manual} to review yourself</div></div>`).join('')}</div></div>
147	<div><div class="sec">Do these next</div><ol class="next">${next.map((t,i)=>{const b=blockers(t);return `<li><button type="button" data-id="${t.id}"><span class="num">${i+1}</span><span><span>${esc(t.name)}</span><div class="why">${esc(areaName(t.functionalAreaId))} › ${esc(t.swimlane)} · ${t.fails.length} of ${t.checks.length} checks fail${b.length?` · after ${b.map(x=>esc(x.name)).join(', ')}`:''}</div></span><span style="display:flex;gap:4px"><span class="pill">${t.phase}</span>${t.priority?`<span class="pill">${t.priority}</span>`:''}</span></button></li>`}).join('')}</ol></div>`;
148	document.querySelectorAll('ol.next button').forEach(b=>b.onclick=()=>select(b.dataset.id,true));
149	const areas=D.areas.map(a=>{const ts=D.tasks.filter(t=>t.functionalAreaId===a.id);const lanes=[];ts.forEach(t=>{const n=t.swimlane||a.name;let l=lanes.find(x=>x.name===n);if(!l)lanes.push(l={name:n,tasks:[]});l.tasks.push(t)});return{...a,tasks:ts,lanes}});
